def lead(t):
    m = re.match(r'^\s*(-?[\d,]+(?:\.\d+)?)', t)
    return float(m.group(1).replace(',', '')) if m else None
bad = 0; n = 0
for f in sorted(glob.glob(os.path.join(HERE, 'e4f', '*.json'))):
    for it in json.load(open(f)):
        n += 1; i = it['id']; spec = CHK[i]
        right = [c for c in it['c'] if c.get('k') == 1]; assert len(right) == 1
        ans = right[0]['t']; wrong = [c['t'] for c in it['c'] if c.get('k') != 1]
        msg = ''
        if spec['calc'] is not None:
            val = eval(spec['calc'])
            a = lead(ans)
            ok = a is not None and abs(a - val) < 1e-9
            wl = [lead(w) for w in wrong]
            unit = lambda t: re.sub(r'^\s*-?[\d,]+(?:\.\d+)?', '', t)
            ok2 = all(w is None or abs(w - val) > 1e-9 or unit(x) != unit(ans) for w, x in zip(wl, wrong))
            msg = f'計算={val:g}'
            if not (ok and ok2): bad += 1; msg += '  <<< NG(正解/まちがい)'
        if spec['chk'] is not None:
            ok = bool(eval(spec['chk']))
            msg += f'  chk={ok}'
            if not ok: bad += 1; msg += '  <<< NG(chk)'
        print(f"{i} | {it['q'][:60]} → 正解『{ans}』 {msg}")
print(n, '問  NG =', bad); sys.exit(1 if bad else 0)
